/* crosswalk cards, r37. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37a"]=[{"q": "The pressure at a place minus the pressure of still air. What is it called?", "a": "the sound pressure p", "w": ["the stiffness", "the intensity", "the wavelength"], "why": "A sound is a change in pressure from still air."}, {"q": "Where the air is thinned, what is the sign of the sound pressure?", "a": "negative", "w": ["positive", "zero", "it has no sign"], "why": "Thinned air is below still air."}, {"q": "A line reads p_tt = c²p_xx for air in a pipe, from the stiffness and motion laws. Which technique licenses it?", "a": "the air-wave technique", "w": ["the sound-pressure technique", "the wavelength technique", "the medium-speed technique"], "why": "The air-wave technique turns the two laws into the wave equation."}, {"q": "What is the speed of sound in air at 20 °C, to the nearest metre a second?", "a": "343 m/s", "w": ["298 m/s", "1480 m/s", "3 × 10⁸ m/s"], "why": "c = √(γP₀/ρ) ≈ 343."}, {"q": "A shout and a whisper cross a field. Which arrives first?", "a": "neither: both at the same speed", "w": ["the shout", "the whisper", "the higher one"], "why": "The medium-speed technique: one speed for every sound in one still medium."}, {"q": "A note of 440 Hz in air. About how long is its wavelength?", "a": "0.78 m", "w": ["3.4 m", "440 m", "0.0023 m"], "why": "λ = c/f = 343/440."}, {"q": "Two numbers of a steady note are 686 Hz and 343 m/s. What is the third?", "a": "a wavelength of 0.5 m", "w": ["a wavelength of 2 m", "a pitch of 343 Hz", "a speed of 686 m/s"], "why": "fλ = c."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37b"]=[{"q": "What is the pitch of a sound that repeats every T seconds?", "a": "1/T hertz", "w": ["T hertz", "the loudest turning", "the lowest turning present"], "why": "Pitch is the rate of the repeat."}, {"q": "A sum of turnings at 200, 300 and 400 Hz. What is its pitch?", "a": "100 Hz", "w": ["200 Hz", "300 Hz", "it has none"], "why": "It repeats every 1/100 s, though nothing at 100 Hz is in it."}, {"q": "About how many octaves does the hearing window hold?", "a": "just under ten", "w": ["seven", "twelve", "a thousand"], "why": "log₂ 1000 ≈ 9.97."}, {"q": "On the pitch line, how far apart are 220 Hz and 440 Hz?", "a": "one octave", "w": ["220 Hz", "twelve octaves", "half an octave"], "why": "The distance is log₂ of the ratio, 2."}, {"q": "About how many cents is a pure fifth, 3/2?", "a": "702", "w": ["700", "386", "1200"], "why": "1200 log₂ 1.5 ≈ 701.955."}, {"q": "A line reads h(g) − h(f) = log₂(g/f). Which technique licenses it?", "a": "the pitch-line technique", "w": ["the repeat-rate technique", "the ten-octave technique", "the wavelength technique"], "why": "The pitch line turns ratios into distances."}, {"q": "Has a steady hiss a pitch, in 37b1’s sense?", "a": "no: it does not repeat", "w": ["yes: its highest turning", "yes: 20 000 Hz", "yes: its loudest turning"], "why": "Only a sound that repeats has a pitch."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37c"]=[{"q": "The power a sound carries through each square metre. What is it called?", "a": "its intensity", "w": ["its level", "its pressure", "its loudness"], "why": "I = ⟨p²⟩/(ρc), in watts a square metre."}, {"q": "Two sounds at different frequencies, each 60 dB. What level together?", "a": "about 63 dB", "w": ["120 dB", "60 dB", "66 dB"], "why": "Their powers add: +3 dB."}, {"q": "A line reads I_(p+q) = I_p + I_q for turnings at different frequencies. Which technique licenses it?", "a": "the adding-power technique", "w": ["the pressure-level technique", "the spreading technique", "the recipe technique"], "why": "The cross term averages to 0 at different frequencies."}, {"q": "Doubling a sound’s pressure changes its level by how much?", "a": "about +6 dB", "w": ["+3 dB", "+20 dB", "doubles the dB"], "why": "20 log₁₀ 2 ≈ 6.02."}, {"q": "In open air, going twice as far from a small source changes the level by how much?", "a": "about −6 dB", "w": ["−3 dB", "halves the dB", "−20 dB"], "why": "The spreading technique: a quarter of the power."}, {"q": "A 1000 Hz note at 80 dB makes a 1100 Hz note at 40 dB disappear. What is this called on the rung?", "a": "a loud sound hiding a quieter neighbour", "w": ["the turn-free technique", "spreading", "fading"], "why": "Laid down in 37c4, measured from listeners."}, {"q": "Two notes at 40 dB, one at 50 Hz and one at 3000 Hz. Which sounds louder?", "a": "the 3000 Hz note", "w": ["the 50 Hz note", "both the same", "neither is heard"], "why": "Loudness is not intensity: the ear is keenest at 2000 to 5000 Hz."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37d"]=[{"q": "The list of amounts and turns of a note’s turnings. What is it called?", "a": "its recipe", "w": ["its quality", "its pitch", "its band"], "why": "Quality is the amounts as shares; the recipe has the turns too."}, {"q": "Two notes that repeat every T are the same sound exactly when what agrees?", "a": "their recipes", "w": ["their pitches", "their levels", "their peaks"], "why": "The recipe technique."}, {"q": "Two speakers in step; the paths differ by half a wavelength. What is heard there?", "a": "nothing of that note", "w": ["twice the pressure", "a beat", "one speaker only"], "why": "The crest-meeting technique: crest meets trough."}, {"q": "440 Hz and 443 Hz together. How many throbs a second?", "a": "3", "w": ["883", "1.5", "443"], "why": "The swell peaks |f₁ − f₂| times a second."}, {"q": "cos t + cos 3t and cos t − cos 3t. What do they share?", "a": "their amounts at every frequency", "w": ["their shape", "their peak", "nothing"], "why": "Only the turn of the third turning differs."}, {"q": "A line reads “the intensity at the nth frequency is rₙ²/(2ρc)”. Which technique uses it to say the turns change no power?", "a": "the turn-free technique", "w": ["the recipe technique", "the crest-meeting technique", "the adding-power technique"], "why": "φₙ does not appear in the intensity."}, {"q": "For a steady note, which part of its recipe is the ear nearly deaf to?", "a": "the turns", "w": ["the amounts", "the pitch", "the level"], "why": "Laid down in 37d4."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37e"]=[{"q": "A medium takes the share α of a sound per metre. How does the level fall?", "a": "by 4.343α dB every metre", "w": ["by α watts a metre", "by half each metre", "by 6 dB per doubling"], "why": "The fading technique: I₀e^(−αx)."}, {"q": "Why does far thunder rumble?", "a": "the air takes the high notes faster", "w": ["the cloud makes only low notes", "echoes add low notes", "sound slows down"], "why": "The far-is-low technique."}, {"q": "What is a medium’s impedance Z?", "a": "its density times its speed", "w": ["its stiffness", "its speed alone", "its share per metre"], "why": "Z = ρc."}, {"q": "About what share of a sound in air goes into water, head on?", "a": "about 0.1%", "w": ["about 50%", "about 99.9%", "all of it"], "why": "The bounce technique: the sides are very unlike."}, {"q": "A line reads R = ((Z₂ − Z₁)/(Z₂ + Z₁))². Which technique licenses it?", "a": "the bounce technique", "w": ["the fading technique", "the echo technique", "the far-is-low technique"], "why": "From equal pressure and equal motion at the boundary."}, {"q": "An echo returns 1 s after a shout. How far is the wall?", "a": "about 172 m", "w": ["343 m", "686 m", "about 86 m"], "why": "d = ct/2."}, {"q": "How far must a single wall be, at least, to be heard as an echo?", "a": "about 8.6 m", "w": ["about 17 m", "about 1 m", "about 343 m"], "why": "Delays under about 50 ms are joined to the sound."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37f"]=[{"q": "Stretches of length 0.02 s. About how close in frequency can two turnings be and still be told apart?", "a": "about 50 Hz", "w": ["about 0.02 Hz", "about 5 Hz", "about 500 Hz"], "why": "The window-trade technique: about 1/T."}, {"q": "In a voice, what sets the pitch?", "a": "the buzz of the folds", "w": ["the formants", "the tube’s length", "the hiss"], "why": "The source-filter technique."}, {"q": "In a voice, what sets the vowel?", "a": "the hills of the tube", "w": ["the buzz rate", "the loudness", "the attack"], "why": "The tube is a filter; its hills are the formants."}, {"q": "A tube 17.5 cm long, closed at one end. Where is its first formant?", "a": "about 490 Hz", "w": ["about 980 Hz", "about 245 Hz", "about 1470 Hz"], "why": "c/(4L) = 343/0.7."}, {"q": "A line reads f_k = (2k − 1)c/(4L). Which technique licenses it?", "a": "the tube technique", "w": ["the source-filter technique", "the wavelength technique", "the window-trade technique"], "why": "A crest at the closed end and 0 at the open end."}, {"q": "Why is “s” hard to hear on an old phone line?", "a": "its band lies mostly above 3400 Hz", "w": ["it has no pitch", "it is too quiet", "the line adds a hiss"], "why": "The hiss-band technique: told apart by the band."}, {"q": "A piano note played backwards sounds like an organ. What has changed?", "a": "its attack and decay", "w": ["its recipe in the middle", "its pitch", "its formants"], "why": "Quality is the recipe and the way it moves."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37g"]=[{"q": "Which decides what a sound name spelled like a letter names?", "a": "the matter at hand", "w": ["the spelling", "the loudness", "the first use"], "why": "The sound-name technique."}, {"q": "A recording of one person saying “ah”. What is it, to the vowel “ah”?", "a": "a member of it", "w": ["the vowel itself", "a subset of it", "its name"], "why": "2d12: in, not the set."}, {"q": "Is 110 Hz in the note A?", "a": "yes", "w": ["no", "only on a piano", "only in equal tuning"], "why": "110 = 440 · 2⁻²; the note is closed under octaves."}, {"q": "A line reads “prove it for 440, and that doubling and halving keep it”. Which technique licenses the conclusion for every member of A?", "a": "the octave-induction technique", "w": ["the voicing technique", "the vowel-set technique", "the sound-name technique"], "why": "The note is the smallest set holding 440 and closed under octaves."}, {"q": "Why is no member of the note E (from 660 Hz) in the note A?", "a": "3/2 is no power of 2", "w": ["660 is too high", "E is a different letter", "the ear hears them apart"], "why": "4j18: one prime list."}, {"q": "A major played as A, C♯, E and as C♯, E, A. Same chord?", "a": "yes, but different sounds", "w": ["no", "yes, and the same sound", "only if in one octave"], "why": "The voicing technique."}, {"q": "“This hiss is an A.” Which is it in the arrangement?", "a": "none: a hiss has no pitch", "w": ["true", "false", "true with a rate"], "why": "37g5."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37h"]=[{"q": "A gain by 2 changes the level by how much?", "a": "about +6 dB", "w": ["+3 dB", "+2 dB", "+20 dB"], "why": "20 log₁₀ 2."}, {"q": "At its corner, how much does the plainest low-pass filter take?", "a": "about 3 dB", "w": ["about 6 dB", "all of it", "about 20 dB"], "why": "The filter-corner technique: gain 1/√2."}, {"q": "Two filters in a chain. What happens to their gains?", "a": "they multiply", "w": ["they add", "the larger wins", "they cancel"], "why": "Each turning is multiplied by both in turn."}, {"q": "When can a filter be undone?", "a": "exactly when its gain is nowhere 0", "w": ["always", "when it is low-pass", "never"], "why": "The undo-filter technique."}, {"q": "What reaches the ear through a canceller?", "a": "the error of its guess", "w": ["silence", "the guess", "the original sound"], "why": "p + q, with q the guess at −p."}, {"q": "A compressor with T = −20 dB and r = 4. Where does −8 dB go?", "a": "−17 dB", "w": ["−2 dB", "−20 dB", "−8 dB"], "why": "T + (x − T)/r."}, {"q": "Which of these cannot be undone?", "a": "a limiter", "w": ["a compressor with ratio 4", "a gain by 0.1", "a low-pass filter that is never 0"], "why": "The level-squeeze technique: a limiter sends many levels to one."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37i"]=[{"q": "120 beats per minute is how many hertz?", "a": "2 Hz", "w": ["120 Hz", "0.5 Hz", "60 Hz"], "why": "120/60."}, {"q": "How many onsets does three against two hold in a bar?", "a": "4", "w": ["5", "6", "3"], "why": "The meet-once technique: p + q − 1."}, {"q": "Four against six. How often do the parts meet in a bar?", "a": "twice", "w": ["once", "never", "six times"], "why": "4 and 6 share 2: two against three, twice."}, {"q": "Three against two with a bar of 1/100 s. What is heard?", "a": "a pure fifth, 300 and 200 Hz", "w": ["a rhythm", "one note at 100 Hz", "a major third"], "why": "The rhythm-is-pitch technique."}, {"q": "Two timekeepers with K = 0.5 and Δω = 0.3. Do they lock?", "a": "yes", "w": ["no", "only if K = Δω", "only at the start"], "why": "The lock-in technique: |Δω| ≤ K."}, {"q": "When locked, what is fixed?", "a": "the gap φ, with sin φ = Δω/K", "w": ["the gap is 0", "both natural rates", "nothing"], "why": "Locked means one rate, a fixed gap."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["37j"]=[{"q": "What does the partly-told technique say of the kept part Ps?", "a": "it is told to within the noise ε", "w": ["it is lost", "it is told only with a rate", "nothing"], "why": "‖Pr − Ps‖ ≤ ε."}, {"q": "What does the partly-told technique say of the lost part s − Ps?", "a": "nothing of it is told", "w": ["it is told to within ε", "it is told in full", "it equals the noise"], "why": "It is at right angles to what is kept."}, {"q": "When is a sound told in full from its shadow?", "a": "when it comes from a known family whose kept parts lie more than 2ε apart", "w": ["always", "never", "when the noise is 0 only"], "why": "The family line of the technique."}, {"q": "A 120 Hz voice on a 300 to 3400 Hz line. What pitch is heard?", "a": "120 Hz", "w": ["360 Hz", "300 Hz", "none"], "why": "The kept harmonics repeat every 1/120 s."}, {"q": "The ear keeps the spectrum and drops the turns. What does the eye do?", "a": "keeps three numbers of a spectrum", "w": ["keeps the turns", "keeps the whole spectrum", "drops nothing"], "why": "36j6: the other half of the blindness."}];
